#!/bin/bash
while read oldrev newrev ref; do
  branch=${ref#refs/heads/}
  case "$branch" in
    main)
      git --git-dir=/git/project --work-tree=/var/www/main checkout -f main ;;
    dev)
      git --git-dir=/git/project --work-tree=/var/www/dev checkout -f dev ;;
  esac
done
EOF
